mapper.select:
SELECT TOP 1 pf.enabled_at
FROM tb_tenant_subscription s
    JOIN tb_plan_feature pf ON pf.plan_id = s.plan_id
WHERE s.tenant_id = #{tenantId}
  AND s.subscription_status = #{subscriptionStatus}
  AND s.starts_at <= GETDATE()
  AND (s.ends_at IS NULL OR s.ends_at > GETDATE())
  AND pf.feature_code = #{featureCode}
ORDER BY s.starts_at DESC

SELECT TOP 1 pf.limit_value
FROM tb_tenant_subscription s
    JOIN tb_plan_feature pf ON pf.plan_id = s.plan_id
WHERE s.tenant_id = #{tenantId}
  AND s.subscription_status = #{subscriptionStatus}
  AND s.starts_at <= GETDATE()
  AND (s.ends_at IS NULL OR s.ends_at > GETDATE())
  AND pf.feature_code = #{featureCode}
  AND pf.feature_type = #{featureType}
  AND pf.enabled_at = #{enabledAt}
ORDER BY s.starts_at DESC

SELECT TOP 1 tenant_id
FROM tb_tenant
WHERE tenant_code = #{value}
